<div class="auth-card auth-card-wide"><div class="auth-heading"><span class="eyebrow">Admissions 2027–28</span><h2>Create applicant account</h2><p>Use an email address you can access throughout the admission process.</p></div><?php if(!$cycle):?><div class="alert alert-warning">The 2027–28 cycle is currently in draft and public registration is not open. An administrator can open it after reviewing institutional rules. The form remains visible for setup testing.</div><?php endif?><form method="post" action="<?= url('register') ?>" class="auth-form"><?= csrf_field() ?><div class="form-grid"><label><span>First name *</span><input name="first_name" value="<?= e(old('first_name')) ?>" required autocomplete="given-name"><?= error('first_name')?'<small class="field-error">'.e(error('first_name')).'</small>':'' ?></label><label><span>Last name *</span><input name="last_name" value="<?= e(old('last_name')) ?>" required autocomplete="family-name"></label><label class="full"><span>Email address *</span><input type="email" name="email" value="<?= e(old('email')) ?>" required autocomplete="email"><?= error('email')?'<small class="field-error">'.e(error('email')).'</small>':'' ?><small>We’ll send your verification link here.</small></label><label class="full"><span>Mobile number *</span><div class="phone-field"><i>+91</i><input name="mobile" value="<?= e(old('mobile')) ?>" required inputmode="numeric" autocomplete="tel" placeholder="10-digit mobile number"></div><?= error('mobile')?'<small class="field-error">'.e(error('mobile')).'</small>':'' ?></label><label><span>Password *</span><input type="password" name="password" required minlength="10" autocomplete="new-password" data-password><small>10+ characters; use upper/lower case, number and symbol.</small></label><label><span>Confirm password *</span><input type="password" name="password_confirmation" required autocomplete="new-password"></label></div><label class="check-control check-control-top"><input type="checkbox" name="terms" value="1" required><span>I agree to the <a href="<?= url('terms') ?>" target="_blank">terms of use</a> and acknowledge the <a href="<?= url('privacy') ?>" target="_blank">privacy notice</a>.</span></label><?= error('terms')?'<small class="field-error">'.e(error('terms')).'</small>':'' ?><button class="button button-primary button-block" type="submit">Create account & verify email →</button></form><p class="auth-switch">Already registered? <a href="<?= url('login') ?>">Sign in</a></p></div>
